J='(sub, id, k) => { document.getElementById("result").hidden = true; const mod = AF.module(sub); const lv = mod.levels.find(l => l.id === id); AF.App.startLevel(mod, Object.assign({ id: "t" + id + k + Math.random(), title: lv.title, tier: lv.tier, lang: mod.lang }, lv.steps[k]), 0); }'
OUT=$1; SIZE=$2
node shots.mjs $SIZE $OUT "choose=js:($J)('math','m1-1',1)@3200" "say=js:($J)('english','en1-1',2)@3200" "sort=js:($J)('math','m1-6',2)@3200" "order=js:($J)('math','m1-3',2)@3200" "memory=js:($J)('english','en1-r',1)@3200" "intro=js:($J)('phonics','ph1-1',0)@3200" "trace=js:($J)('phonics','ph1-1',1)@4200" "build=js:($J)('phonics','ph2-1',2)@3200" "match=js:($J)('phonics','ph1-2',2)@3200" "story=js:($J)('english','en1-1',0)@3200" "pop=js:($J)('phonics','ph1-1',2)@4200" "maze=js:($J)('math','m1-8',2)@3200"
